#include "data_include.h"

typedef struct {
	uint16_t* ops;
	size_t* ops_len;
	size_t ops_i;

	uint8_t* data;
	size_t* data_len;
	size_t data_i;
	uint32_t* instruction_counter;

	fd_state_t* user_data;

} interpreter_t;


#include "bytecode_spec.h"

//=========================
//atomic data type functions
//=========================

d_u16* read_d_u16(interpreter_t* vm){
	ASSERT(vm->data_i + sizeof(d_u16) <= *vm->data_len);
	STATIC_ASSERT(sizeof(d_u16) == 2, "size missmatch in d_u16");
	d_u16* res = (d_u16*)&vm->data[vm->data_i];
	vm->data_i += sizeof(d_u16);
	return res;
}

d_u32* read_d_u32(interpreter_t* vm){
	ASSERT(vm->data_i + sizeof(d_u32) <= *vm->data_len);
	STATIC_ASSERT(sizeof(d_u32) == 4, "size missmatch in d_u32");
	d_u32* res = (d_u32*)&vm->data[vm->data_i];
	vm->data_i += sizeof(d_u32);
	return res;
}


//=========================
//edge type functions
//=========================


//=========================
//interpreter functions
//=========================

interpreter_t* new_interpreter(){
	interpreter_t* vm = VM_MALLOC(sizeof(interpreter_t));
	vm->ops = 0;
	vm->ops_len = 0;
	vm->data = 0;
	vm->data_len = 0;
	vm->user_data = NULL;



	return vm;
}

void init_interpreter(interpreter_t* vm, uint16_t* ops, size_t* ops_len, uint8_t* data, size_t* data_len, uint32_t* instruction_counter){
	vm->ops=ops;
	vm->ops_len=ops_len;
	vm->ops_i = 0;
	vm->data = data;
	vm->data_i = 0;
	vm->data_len=data_len;
	vm->user_data = NULL;
	vm->instruction_counter = instruction_counter;
}

